SELECT l.previousdoc AS invoice_id, p.tranid AS invoice, l.nextdoc AS applied_id, n.tranid AS applied_doc, n.type AS applied_type, TO_CHAR(n.trandate, 'YYYY-MM-DD') AS applied_date, l.linktype, l.foreignamount FROM previoustransactionlinelink l JOIN transaction p ON p.id = l.previousdoc JOIN transaction n ON n.id = l.nextdoc WHERE l.previousdoc IN (:doc_ids) AND n.type IN ('CustPymt', 'CustCred', 'Journal', 'CustDep') ORDER BY l.previousdoc, l.nextdoc, l.linktype
